-- FUNC12 Recursos Humanos e Folha de Pagamento
create schema if not exists sigov;
create table if not exists sigov.rh_servidor (id bigint generated by default as identity primary key, nome varchar(200) not null, cpf varchar(11) not null, matricula varchar(50) not null, data_nascimento date not null, sexo varchar(20), email varchar(180), telefone varchar(30), endereco text, escolaridade varchar(100), situacao varchar(20) not null default 'ATIVO' check(situacao in ('ATIVO','INATIVO','AFASTADO','DESLIGADO')), exclusao_justificativa text, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_cargo (id bigint generated by default as identity primary key, codigo varchar(50) not null, nome varchar(180) not null, descricao text, carga_horaria numeric(6,2) check(carga_horaria>0), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_funcao (id bigint generated by default as identity primary key, codigo varchar(50) not null, nome varchar(180) not null, descricao text, gratificacao numeric(14,2) not null default 0 check(gratificacao>=0), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_unidade_lotacao (id bigint generated by default as identity primary key, codigo varchar(50) not null, nome varchar(180) not null, secretaria varchar(180), unidade_pai_id bigint references sigov.rh_unidade_lotacao(id), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_vinculo (id bigint generated by default as identity primary key, servidor_id bigint not null references sigov.rh_servidor(id), matricula_vinculo varchar(50) not null, tipo_vinculo varchar(60) not null, regime varchar(60) not null, cargo_id bigint not null references sigov.rh_cargo(id), funcao_id bigint references sigov.rh_funcao(id), unidade_lotacao_id bigint references sigov.rh_unidade_lotacao(id), data_admissao date not null, data_desligamento date, motivo_desligamento text, carga_horaria numeric(6,2) not null check(carga_horaria>0), salario_base numeric(14,2) not null check(salario_base>=0), situacao varchar(20) not null default 'ATIVO' check(situacao in ('ATIVO','AFASTADO','CEDIDO','DESLIGADO','SUSPENSO')), check(situacao<>'DESLIGADO' or (data_desligamento is not null and nullif(btrim(motivo_desligamento),'') is not null)), check(data_desligamento is null or data_desligamento>=data_admissao), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_lotacao_historico (id bigint generated by default as identity primary key, vinculo_id bigint not null references sigov.rh_vinculo(id), unidade_lotacao_id bigint not null references sigov.rh_unidade_lotacao(id), inicio date not null, fim date, motivo text, check(fim is null or fim>=inicio), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_dependente (id bigint generated by default as identity primary key, servidor_id bigint not null references sigov.rh_servidor(id), nome varchar(200) not null, cpf varchar(11), data_nascimento date not null, parentesco varchar(60) not null, dependente_ir boolean not null default false, dependente_salario_familia boolean not null default false, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_frequencia (id bigint generated by default as identity primary key, vinculo_id bigint not null references sigov.rh_vinculo(id), data date not null, entrada time, saida time, horas_trabalhadas numeric(6,2) not null default 0 check(horas_trabalhadas>=0), falta boolean not null default false, falta_justificada boolean not null default false, atraso_minutos integer not null default 0 check(atraso_minutos>=0), justificativa text, status varchar(20) not null default 'PENDENTE' check(status in ('PENDENTE','APROVADA','REJEITADA','HOMOLOGADA')), apontamento_manual boolean not null default true, check(saida is null or entrada is null or saida>=entrada), check(not falta_justificada or nullif(btrim(justificativa),'') is not null), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_ferias (id bigint generated by default as identity primary key, vinculo_id bigint not null references sigov.rh_vinculo(id), aquisitivo_inicio date not null, aquisitivo_fim date not null, concessivo_limite date not null, inicio date not null, fim date not null, dias integer not null check(dias>0), abono_dias integer not null default 0 check(abono_dias>=0 and abono_dias<=dias), status varchar(20) not null default 'PROGRAMADA' check(status in ('PROGRAMADA','APROVADA','EM_GOZO','CONCLUIDA','CANCELADA')), justificativa text, check(aquisitivo_fim>=aquisitivo_inicio and fim>=inicio), check(status<>'CANCELADA' or nullif(btrim(justificativa),'') is not null), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_afastamento (id bigint generated by default as identity primary key, vinculo_id bigint not null references sigov.rh_vinculo(id), tipo varchar(80) not null, inicio date not null, fim date, cid_protegido bytea, documento_referencia varchar(200), status varchar(20) not null default 'ATIVO' check(status in ('ATIVO','ENCERRADO','CANCELADO')), observacao text, justificativa text, impacta_folha boolean not null default false, check(fim is null or fim>=inicio), check(status<>'CANCELADO' or nullif(btrim(justificativa),'') is not null), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_evento_folha (id bigint generated by default as identity primary key, codigo varchar(50) not null, descricao varchar(180) not null, tipo varchar(20) not null check(tipo in ('PROVENTO','DESCONTO','BASE','INFORMATIVO')), natureza varchar(80) not null, modo_calculo varchar(20) not null check(modo_calculo in ('FIXO','PERCENTUAL','FORMULA')), valor_fixo numeric(14,2), percentual numeric(9,4), formula text, incide_previdencia boolean not null default false, incide_irrf boolean not null default false, incide_fgts boolean not null default false, incide_margem boolean not null default false, incide_liquido boolean not null default true, permite_liquido_negativo boolean not null default false, exige_justificativa_negativo boolean not null default true, check(valor_fixo is null or valor_fixo>=0), check(percentual is null or percentual>=0), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_folha_competencia (id bigint generated by default as identity primary key, competencia date not null, status varchar(30) not null default 'ABERTA' check(status in ('ABERTA','CALCULADA','HOMOLOGADA','ENVIADA_FINANCEIRO','CANCELADA')), total_bruto numeric(16,2) not null default 0 check(total_bruto>=0), total_descontos numeric(16,2) not null default 0 check(total_descontos>=0), total_liquido numeric(16,2) not null default 0, justificativa text, calculada_at timestamptz, homologada_at timestamptz, check(date_trunc('month',competencia)::date=competencia), check(status not in ('CANCELADA') or nullif(btrim(justificativa),'') is not null), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_evento_recorrente (id bigint generated by default as identity primary key, vinculo_id bigint not null references sigov.rh_vinculo(id), evento_id bigint not null references sigov.rh_evento_folha(id), inicio date not null, fim date, valor numeric(14,2), percentual numeric(9,4), justificativa text, check(fim is null or fim>=inicio), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_evento_variavel (id bigint generated by default as identity primary key, competencia_id bigint not null references sigov.rh_folha_competencia(id), vinculo_id bigint not null references sigov.rh_vinculo(id), evento_id bigint not null references sigov.rh_evento_folha(id), quantidade numeric(12,4) not null default 1, valor numeric(14,2) not null check(valor>=0), justificativa text, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_folha_calculo (id bigint generated by default as identity primary key, competencia_id bigint not null references sigov.rh_folha_competencia(id), vinculo_id bigint not null references sigov.rh_vinculo(id), servidor_id bigint not null references sigov.rh_servidor(id), salario_base numeric(14,2) not null, bruto numeric(16,2) not null default 0, descontos numeric(16,2) not null default 0, base_previdencia numeric(16,2) not null default 0, base_irrf numeric(16,2) not null default 0, base_fgts numeric(16,2) not null default 0, liquido numeric(16,2) not null, versao integer not null default 1 check(versao>0), homologado boolean not null default false, check(bruto>=0 and descontos>=0), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_folha_calculo_item (id bigint generated by default as identity primary key, calculo_id bigint not null references sigov.rh_folha_calculo(id), evento_id bigint references sigov.rh_evento_folha(id), codigo varchar(50) not null, descricao varchar(180) not null, tipo varchar(20) not null check(tipo in ('PROVENTO','DESCONTO','BASE','INFORMATIVO')), referencia numeric(14,4), valor numeric(16,2) not null, origem varchar(30) not null check(origem in ('SALARIO_BASE','RECORRENTE','VARIAVEL','FREQUENCIA','AFASTAMENTO','REGRA')), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_holerite_acesso (id bigint generated by default as identity primary key, calculo_id bigint not null references sigov.rh_folha_calculo(id), usuario_id bigint, acao varchar(20) not null check(acao in ('VISUALIZAR','EXPORTAR')), correlation_id varchar(100), ip inet, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_integracao_financeira (id bigint generated by default as identity primary key, competencia_id bigint not null references sigov.rh_folha_competencia(id), unidade_lotacao_id bigint references sigov.rh_unidade_lotacao(id), natureza varchar(80) not null, bruto numeric(16,2) not null default 0, descontos numeric(16,2) not null default 0, liquido numeric(16,2) not null default 0, status varchar(20) not null default 'PENDENTE' check(status in ('PENDENTE','GERADO','ENVIADO','CANCELADO')), justificativa text, correlation_id varchar(100), check(status<>'CANCELADO' or nullif(btrim(justificativa),'') is not null), tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
create table if not exists sigov.rh_auditoria (id bigint generated by default as identity primary key, acao varchar(40) not null, recurso varchar(80) not null, registro_id bigint, usuario_id bigint, antes jsonb, depois jsonb, correlation_id varchar(100), ip inet, tenant_id bigint not null, entidade_id bigint not null, ativo boolean not null default true, is_deleted boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz, created_by bigint, updated_by bigint, deleted_by bigint, dados jsonb not null default '{}'::jsonb, auditoria jsonb not null default '{}'::jsonb);
